import { Group, Mesh, BoxGeometry, MeshStandardNodeMaterial, Color, Vector3 } from 'three/webgpu';
import { uv, mix, uniform, add, mul } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup } = ctx.THREE;

  // Root container
  const root = new ThreeGroup();
  root.name = 'BentoMetricsGrid';

  // Gradient colors
  const gradStart = new Color('#101017');
  const gradEnd = new Color('#1a1a22');

  // Helper to create a tile mesh with gradient material
  function createTile(width, height, depth = 0.06) {
    const geometry = new BoxGeometry(width, height, depth);
    const material = new MeshStandardNodeMaterial({
      metalness: 0.45,
      roughness: 0.5,
      clearcoat: 0.2,
      transparent: true,
      // Gradient node (135° diagonal)
      colorNode: mix(
        uniform(gradStart),
        uniform(gradEnd),
        mul(add(uv().x, uv().y), 0.5)
      )
    });
    material.opacity = 1; // start visible for entrance animation
    const mesh = new Mesh(geometry, material);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return { mesh, material, geometry };
  }

  // Helper to create tick bar
  function createTickBar() {
    const geometry = new BoxGeometry(0.4, 0.05, 0.02);
    const material = new MeshStandardNodeMaterial({
      emissive: new Color('#ff2a38'),
      emissiveIntensity: 1.3,
      metalness: 0,
      roughness: 1,
      color: 0x000000
    });
    const mesh = new Mesh(geometry, material);
    mesh.position.set(0, 0, 0.04);
    return { mesh, material, geometry };
  }

  // Text creation helper
  function addText(parent, content, opts = {}) {
    const txt = ctx.fontAtlas.createText(content, opts);
    parent.add(txt);
    return txt;
  }

  // Grid layout constants
  const totalWidth = 5.5;
  const totalHeight = 3.5;
  const gutter = 0.25;
  const depth = 0.06;
  const padding = 0.5;

  // Dominant cell
  const domWidth = 3.25;
  const domHeight = 3.5;
  const domX = -totalWidth / 2 + domWidth / 2; // -1.125
  const domY = 0;

  const domGroup = new Group();
  domGroup.position.set(domX, domY, 0);
  const domTile = createTile(domWidth, domHeight, depth);
  domGroup.add(domTile.mesh);
  // Tick bar for dominant cell
  const domTick = createTickBar();
  domTick.mesh.position.set(
    -domWidth / 2 + padding + 0.2,
    domHeight / 2 - padding - 0.025,
    0
  );
  domGroup.add(domTick.mesh);

  // Text for dominant cell
  addText(domGroup, '0.002 mm', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1
  }).position.set(0, 0.2, 0.07);
  addText(domGroup, 'Case tolerance, CNC pass', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1.4
  }).position.set(0, -0.6, 0.07);

  root.add(domGroup);

  // Secondary cells (right column)
  const secWidth = 2.0;
  const secHeight = 1.625;
  const rightX = totalWidth / 2 - secWidth / 2; // +2.0

  const topY = totalHeight / 2 - secHeight / 2; // +0.9375
  const botY = -topY; // -0.9375

  // Top-right cell
  const topGroup = new Group();
  topGroup.position.set(rightX, topY, 0);
  const topTile = createTile(secWidth, secHeight, depth);
  topGroup.add(topTile.mesh);
  const topTick = createTickBar();
  topTick.mesh.position.set(
    -secWidth / 2 + padding + 0.2,
    secHeight / 2 - padding - 0.025,
    0
  );
  topGroup.add(topTick.mesh);
  addText(topGroup, '38 h', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1.05
  }).position.set(0, 0.1, 0.07);
  addText(topGroup, 'Power reserve, NA-01', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1.4
  }).position.set(0, -0.5, 0.07);
  root.add(topGroup);

  // Bottom-right cell
  const botGroup = new Group();
  botGroup.position.set(rightX, botY, 0);
  const botTile = createTile(secWidth, secHeight, depth);
  botGroup.add(botTile.mesh);
  const botTick = createTickBar();
  botTick.mesh.position.set(
    -secWidth / 2 + padding + 0.2,
    secHeight / 2 - padding - 0.025,
    0
  );
  botGroup.add(botTick.mesh);
  addText(botGroup, '214', {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1.05
  }).position.set(0, 0.1, 0.07);
  addText(botGroup, 'Components per calibre', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    lineHeight: 1.4
  }).position.set(0, -0.5, 0.07);
  root.add(botGroup);

  // Header caption above grid
  const header = addText(root, 'ATELIER METRICS / Q2 2026', {
    fontSize: 18,
    color: '#ff2a38',
    align: 'left',
    lineHeight: 1.4
  });
  header.position.set(-totalWidth / 2, totalHeight / 2 + 0.5, 0.07);

  // Assemble all tile groups for animation and interaction
  const tileGroups = [domGroup, topGroup, botGroup];
  const allMeshes = [];

  tileGroups.forEach((g) => {
    g.traverse((obj) => {
      if (obj.isMesh) allMeshes.push(obj);
    });
    // Interaction handlers
    g.userData.handlers = {
      hover: () => {
        const tl = gsap.timeline();
        tl.to(g.scale, {
          x: 0.97,
          y: 0.97,
          z: 0.97,
          duration: 0.12,
          ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
        });
        g.userData._hoverTl = tl;
      },
      leave: () => {
        const tl = gsap.timeline();
        tl.to(g.scale, {
          x: 1.04,
          y: 1.04,
          z: 1.04,
          duration: 0.9,
          ease: 'cubic-bezier(0.165,0.84,0.44,1)'
        }).to(g.scale, {
          x: 1,
          y: 1,
          z: 1,
          duration: 0.3,
          ease: 'power4.out'
        });
        g.userData._leaveTl = tl;
      }
    };
  });

  // Entrance animation: staggered fade-up
  const entranceTL = gsap.timeline();
  tileGroups.forEach((g, i) => {
    entranceTL.from(
      g.position,
      {
        y: '+=0.2',
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      i * 0.08
    );
    entranceTL.from(
      g.children.map((c) => (c.material ? c.material : {})),
      {
        opacity: 0,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      },
      i * 0.08
    );
  });
  entranceTL.play();

  // Cleanup logic
  root.userData.cleanup = () => {
    entranceTL.kill();
    tileGroups.forEach((g) => {
      if (g.userData._hoverTl) g.userData._hoverTl.kill();
      if (g.userData._leaveTl) g.userData._leaveTl.kill();
      g.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose && m.dispose());
            } else {
              obj.material.dispose && obj.material.dispose();
            }
          }
        }
      });
    });
    // Dispose header text (if it has resources)
    if (header && header.traverse) {
      header.traverse((obj) => {
        if (obj.isMesh && obj.geometry) obj.geometry.dispose();
        if (obj.isMesh && obj.material) obj.material.dispose();
      });
    }
  };

  return root;
}
